    /**
     * Tests creating a new SerialNumber.
     *
     * @return    SerialNumber
     */
    public SerialNumber testCreate() throws Throwable {
    SerialNumber entity = null;

    LOGGER.info( "SerialNumberTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a SerialNumber");

    StringBuilder msg = new StringBuilder( "-- Failed to create a SerialNumber" );

    try {
        entity = service.createSerialNumber( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getSerialNumberId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a SerialNumber with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

