    /**
     * Tests getting all SerialNumbers.
     *
     * @return    Collection
     */
    public List<SerialNumber> testGetAll() throws Throwable {
    LOGGER.info( "SerialNumberTest:testGetAll() - Retrieving Collection of SerialNumbers:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all SerialNumber : " );
    List<SerialNumber> collection  = null;

    try {
        // call the static get method on the SerialNumberService
        collection = service.getAllSerialNumber();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            SerialNumber currEntity  = null;
            Iterator<SerialNumber> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSerialNumberId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

